package com.chickencenter.ui.controllers;import com.chickencenter.model.Item;import com.chickencenter.model.Vendor;import com.chickencenter.service.StockService;import com.chickencenter.service.ExpenseService;import com.chickencenter.dao.ItemDAO;import com.chickencenter.util.ToastManager;import javafx.collections.FXCollections;import javafx.collections.ObservableList;import javafx.fxml.FXML;import javafx.scene.control.*;import java.sql.SQLException;public class InventoryController {    @FXML private TableView<Item> tblInventory;    @FXML private TableColumn<Item, Integer> colId;    @FXML private TableColumn<Item, String> colName;    @FXML private TableColumn<Item, String> colUnit;    @FXML private TableColumn<Item, Integer> colVendor;    @FXML private TableColumn<Item, Double> colStock;    @FXML private TableColumn<Item, Double> colPrice;    @FXML private TextField txtName;    @FXML private TextField txtUnit;    @FXML private ComboBox<VendorComboItem> cmbVendor;    @FXML private Button btnAdd;    @FXML private Button btnUpdate;    @FXML private Button btnDelete;    private final ItemDAO itemDAO;    private final StockService stockService;    private final ExpenseService expenseService;    private final ObservableList<Item> itemList;    private final ObservableList<VendorComboItem> vendorList;    private Item selectedItem;    public InventoryController() {        this.itemDAO = new ItemDAO();        this.stockService = new StockService();        this.expenseService = new ExpenseService();        this.itemList = FXCollections.observableArrayList();        this.vendorList = FXCollections.observableArrayList();    }    @FXML    public void initialize() {        setupTable();        loadVendors();        loadItems();                cmbVendor.setButtonCell(new ListCell<VendorComboItem>() {            protected void updateItem(VendorComboItem item, boolean empty) {                super.updateItem(item, empty);                if (empty || item == null) {                    setText("Select Vendor");                } else {                    setText(item.getName());                }            }        });                cmbVendor.setPromptText("Select Vendor");    }    private void setupTable() {        tblInventory.setSelectionModel(null);        tblInventory.setColumnResizePolicy(TableView.UNCONSTRAINED_RESIZE_POLICY);                colId.setCellValueFactory(cellData -> new javafx.beans.property.SimpleIntegerProperty(cellData.getValue().getId()).asObject());        colName.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().getName()));        colUnit.setCellValueFactory(cellData -> new javafx.beans.property.SimpleStringProperty(cellData.getValue().getUnit()));        colVendor.setCellValueFactory(cellData -> new javafx.beans.property.SimpleIntegerProperty(cellData.getValue().getVendorId()).asObject());        colStock.setCellValueFactory(cellData -> {            try {                double qty = stockService.getStockQuantity(cellData.getValue().getId());                return new javafx.beans.property.SimpleDoubleProperty(qty).asObject();            } catch (SQLException e) {                return new javafx.beans.property.SimpleDoubleProperty(0).asObject();            }        });        colPrice.setCellValueFactory(cellData -> {            try {                double price = stockService.getCurrentPurchasePrice(cellData.getValue().getId());                return new javafx.beans.property.SimpleDoubleProperty(price).asObject();            } catch (SQLException e) {                return new javafx.beans.property.SimpleDoubleProperty(0).asObject();            }        });        tblInventory.setItems(itemList);        tblInventory.getSelectionModel().selectedItemProperty().addListener((obs, old, newVal) -> {            selectedItem = newVal;            if (newVal != null) {                txtName.setText(newVal.getName());                txtUnit.setText(newVal.getUnit());            }        });    }    private void loadVendors() {        try {            vendorList.clear();            var vendors = expenseService.getAllVendors();            System.out.println("Loading " + vendors.size() + " vendors");            for (Vendor v : vendors) {                vendorList.add(new VendorComboItem(v.getId(), v.getName()));            }            cmbVendor.setItems(vendorList);        } catch (SQLException e) {            e.printStackTrace();            showError("Error loading vendors: " + e.getMessage());        }    }    private void loadItems() {        try {            itemList.clear();            var items = stockService.getAllItemsWithStock();            System.out.println("Loading " + items.size() + " items");            itemList.addAll(items);            tblInventory.refresh();        } catch (SQLException e) {            e.printStackTrace();            showError("Error loading items: " + e.getMessage());        }    }    @FXML    private void addItem() {        if (txtName.getText().isEmpty() || txtUnit.getText().isEmpty()) {            showError("Please fill all fields");            return;        }        VendorComboItem selectedVendor = cmbVendor.getSelectionModel().getSelectedItem();        int vendorId = selectedVendor != null ? selectedVendor.getId() : 1;        try {            Item item = new Item(txtName.getText(), vendorId, txtUnit.getText());            int itemId = itemDAO.create(item);            loadItems();            clearFields();            ToastManager.showSuccess("Item added successfully");        } catch (SQLException e) {            showError("Error adding item: " + e.getMessage());        }    }    @FXML    private void updateItem() {        if (selectedItem == null) {            showError("Please select an item to update");            return;        }        VendorComboItem selectedVendor = cmbVendor.getSelectionModel().getSelectedItem();        int vendorId = selectedVendor != null ? selectedVendor.getId() : selectedItem.getVendorId();        try {            selectedItem.setName(txtName.getText());            selectedItem.setUnit(txtUnit.getText());            selectedItem.setVendorId(vendorId);            itemDAO.update(selectedItem);            loadItems();            clearFields();            ToastManager.showSuccess("Item updated successfully");        } catch (SQLException e) {            showError("Error updating item: " + e.getMessage());        }    }    @FXML    private void deleteItem() {        if (selectedItem == null) {            showError("Please select an item to delete");            return;        }        Alert confirm = new Alert(Alert.AlertType.CONFIRMATION);        confirm.setTitle("Confirm Delete");        confirm.setContentText("Delete " + selectedItem.getName() + "?");        if (confirm.showAndWait().get() == ButtonType.OK) {            try {                itemDAO.delete(selectedItem.getId());                loadItems();                clearFields();                ToastManager.showSuccess("Item deleted successfully");            } catch (SQLException e) {                showError("Error deleting item: " + e.getMessage());            }        }    }    @FXML    private void updateStock() {        if (selectedItem == null) {            showError("Please select an item");            return;        }        TextInputDialog dialog = new TextInputDialog();        dialog.setTitle("Update Stock");        dialog.setHeaderText("Enter new stock quantity for " + selectedItem.getName());        dialog.setContentText("Quantity:");        dialog.showAndWait().ifPresent(qtyStr -> {            try {                double newQty = Double.parseDouble(qtyStr);                if (newQty >= 0) {                    stockService.updateStockManually(selectedItem.getId(), newQty);                    loadItems();                    ToastManager.showSuccess("Stock updated successfully");                }            } catch (NumberFormatException e) {                showError("Invalid quantity");            } catch (SQLException e) {                showError("Error updating stock: " + e.getMessage());            }        });    }    private void clearFields() {        txtName.clear();        txtUnit.clear();                cmbVendor.setButtonCell(new ListCell<VendorComboItem>() {            protected void updateItem(VendorComboItem item, boolean empty) {                super.updateItem(item, empty);                if (empty || item == null) {                    setText("Select Vendor");                } else {                    setText(item.getName());                }            }        });        cmbVendor.getSelectionModel().clearSelection();        cmbVendor.setValue(null);        if (cmbVendor.getEditor() != null) {            cmbVendor.getEditor().clear();        }        cmbVendor.setPromptText("Select Vendor");                selectedItem = null;    }    private void showError(String message) {        Alert alert = new Alert(Alert.AlertType.ERROR);        alert.setTitle("Error");        alert.setHeaderText(null);        alert.setContentText(message);        alert.showAndWait();    }    public static class VendorComboItem {        private final int id;        private final String name;        public VendorComboItem(int id, String name) { this.id = id; this.name = name; }        public int getId() { return id; }        public String getName() { return name; }        public String toString() { return name; }    }}
